        if (count_ == 0) {
            throw std::domain_error("buffer is empty");
        }
        T item = data_[read_index_];
        read_index_ = (read_index_ + 1) % data_.size();
        --count_;
        return item;
    }

    void clear() {
        read_index_ = 0;
        write_index_ = 0;
        count_ = 0;
    }

private:
